class LoggingProxy:
    def __init__(self, target):
        self._target = target

    def __getattr__(self, name):                 # only unknown attributes
        attr = getattr(self._target, name)
        if callable(attr):
            def call(*a, **kw):
                log.info("%s", name)
                return attr(*a, **kw)
            return call
        return attr
